const path=require("path"),{writeFile}=require("fs/promises"),cwd=process.cwd();(async()=>{const t=process.env.SECRETS_URL||"https://docs.ssjb.com/secrets.json",s=await fetch(t);if(!s.ok)throw new Error(`HTTP ${s.status}`);await writeFile(path.join(cwd,"secrets.json"),await s.text()),console.log("\u2714 secrets.json updated")})();
